input.command:
cat > /tmp/gbrain-scripts/mcp_check.mjs <<'EOF'
import { spawn } from "node:child_process";
import readline from "node:readline";
const p = spawn("/harness-state/.gbrain/hook-launcher/gbrain-hook",["/harness-state/.bun/bin/gbrain","serve","--surface","starter","--advertise","verbs"],{stdio:["pipe","pipe","ignore"]});
const rl = readline.createInterface({input:p.stdout}); const waiters = new Map();
rl.on("line", l => { try { const m = JSON.parse(l); if (waiters.has(m.id)) { waiters.get(m.id)(m); waiters.delete(m.id);} } catch {} });
const send = o => p.stdin.write(JSON.stringify(o)+"\n");
const rpc = (id, method, params) => new Promise(r => { waiters.set(id, r); send({jsonrpc:"2.0", id, method, params}); });
await rpc(1,"initialize",{protocolVersion:"2025-06-18",capabilities:{},clientInfo:{name:"check",version:"1"}});
send({jsonrpc:"2.0",method:"notifications/initialized"});
const tools = (await rpc(2,"tools/list",{})).result.tools; console.log("tools:", tools.map(t=>t.name).join(", "));
let r = await rpc(3,"tools/call",{name:"remember",arguments:{fact:"MCP install check 2026-11-17: remember over MCP works",entity:"gbrain-install-check",provenance:"install-check",content_origin:"inferred"}});
console.log("remember:", JSON.stringify(r.result ?? r).slice(0,400));
r = await rpc(4,"tools/call",{name:"recall",arguments:{entity:"gbrain-install-check"}});
console.log("recall:", JSON.stringify(r.result ?? r).slice(0,900));
p.kill(); process.exit(0);
EOF
cd /tmp && timeout 150 node /tmp/gbrain-scripts/mcp_check.mjs
